class TFMLogicBlockItemInfo extends TFMLogicBlock implements TFMLogicBlockDataCollectionInterface
{
}

Method.Source:
public TFMRegistrationCollectors registrationCollectors()
{
    TFMRegistrationCollectors ret = TFMRegistrationCollectors::Construct();

    TFMRegistrationCollectorInformation itemInfo = new TFMRegistrationCollectorInformation(10, 'info', '{ItemNumber}', '', '');

    TFMConditions conditions = TFMConditions::Construct();
    conditions.addCondition(TFMCondition::Construct(classStr(TFMLogicContextInfoContext),conNull(),'ItemInformation'),methodStr(TFMRegistrationCollector,parmHelpLabel) );
    itemInfo.parmConditions(conditions);

    ret.addCollector(itemInfo);

    return ret;
}

/// <summary>
/// Name of the block Type.
/// </summary>
/// <returns>Name of the block</returns>
public Name blockName()
{
    return "@TFM:ShowItemInfo";
}
